L.append("            <div className=\"space-y-2\">{(() => { const zInv: Record<string, number> = {}; " + VAR + ".forEach((r) => { zInv[r.zone] = (zInv[r.zone] || 0) + r.investmentCr; }); return Object.entries(zInv).sort((a, b) => b[1] - a[1]).map(([zone, inv]) => { const pct = (inv as number / kpiData.total) * 100; return <div key={zone} className=\"flex items-center gap-2\"><span className=\"text-xs w-16\">{zone as string}</span><div className=\"flex-1 h-2 bg-muted rounded-full\"><div className=\"h-2 rounded-full\" style={{ width: `${pct}%`, backgroundColor: themeColor }} /></div><span className=\"text-xs font-medium\">&#8377;{inv as number}Cr</span></div>; }); })()}</div>")
L.append("          </CardContent></Card>")
L.append("          <Card><CardHeader><CardTitle className=\"text-base\">Purity Distribution</CardTitle></CardHeader><CardContent>")
L.append("            <div className=\"space-y-2\">")
L.append("              {(() => { const ranges = { '99%+': 0, '95-98.9%': 0, '90-94.9%': 0, '<90%': 0 }; " + VAR + ".forEach((r) => { if (r.purityPercent >= 99) ranges['99%+']++; else if (r.purityPercent >= 95) ranges['95-98.9%']++; else if (r.purityPercent >= 90) ranges['90-94.9%']++; else ranges['<90%']++; }); return (Object.entries(ranges) as [string, number][]).filter(([, v]) => v > 0).map(([range, count]) => { const pct = (count / " + VAR + ".length) * 100; return <div key={range} className=\"flex items-center gap-2\"><span className=\"text-xs w-24\">{range}</span><div className=\"flex-1 h-2 bg-muted rounded-full\"><div className=\"h-2 rounded-full\" style={{ width: `${pct}%`, backgroundColor: themeColor }} /></div><span className=\"text-xs font-medium\">{count}</span></div>; }); })()}")
L.append("            </div>")
L.append("          </CardContent></Card>")
L.append("        </div>")
L.append("      )}")
# Insights tab
L.append("      {activeTab === 'insights' && (")
L.append("        <div className=\"grid grid-cols-1 md:grid-cols-2 gap-4\">")
L.append("          <Card><CardHeader><CardTitle className=\"text-base\">Supply Chain Intelligence</CardTitle></CardHeader><CardContent><div className=\"space-y-3 text-sm\">")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-red-500 bg-red-50/50\"><div className=\"font-medium\">Nuclear Ceramics Demand</div><div className=\"text-xs text-muted-foreground mt-1\">BHAVINI PFBR and IGCAR dual programme driving 99.5%+ nuclear magnesia &#8594; &#8377;940Cr for 800 tonnes &#8594; highest purity segment</div></div>")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-red-500 bg-red-50/50\"><div className=\"font-medium\">Steel Refractory Cycle</div><div className=\"text-xs text-muted-foreground mt-1\">Tata Steel BOF + SAIL ladle + JSW degasser + Tata tundish form &#8594; &#8377;2,620Cr combined &#8594; cyclical lining replacement demand</div></div>")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-red-500 bg-red-50/50\"><div className=\"font-medium\">Space Programme Growth</div><div className=\"text-xs text-muted-foreground mt-1\">ISRO PSLV and GSLV expanded launch cadence driving fused cast magnesia nozzle demand &#8594; &#8377;860Cr for DRDO/ISRO</div></div>")
