L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-red-500 bg-red-50/50\"><div className=\"font-medium\">Total Portfolio: &#8377;{kpiData.total.toLocaleString()} Cr</div><div className=\"text-xs text-muted-foreground mt-1\">Across 14 magnesia and dolomite grades spanning steel, space, nuclear, pharma, construction and naval &#8594; avg purity {kpiData.avgPurity}%</div></div>")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-red-500 bg-red-50/50\"><div className=\"font-medium\">Critical Priority: 4 Records</div><div className=\"text-xs text-muted-foreground mt-1\">Tata Steel BOF &#8594; ISRO nozzle &#8594; BHEL boiler &#8594; BHAVINI breeder &#8594; national infrastructure dependent</div></div>")
L.append("            <div className=\"p-3 rounded-lg border-l-4 border-l-red-500 bg-red-50/50\"><div className=\"font-medium\">Top Manufacturers</div><div className=\"text-xs text-muted-foreground mt-1\">IGCAR &#8594; DRDO &#8594; BHEL lead R&amp;D demand &#8594; Dalmia &#8594; Ramco &#8594; Tata Refractories drive commercial</div></div>")
